function CategoryIcon({ cat, color, sz = 56 }) {
  const icon = ICONS[cat];
  if (!icon) return (
    <svg viewBox="0 0 60 60" width={sz} height={sz} style={{display:'block'}}>
      <rect x="8" y="8" width="44" height="44" fill="none" stroke={color} strokeWidth="2"/>
      <text x="30" y="32" textAnchor="middle" fontSize="8" fill={color}>{cat}</text>
    </svg>
  );
  return (
    <svg
      viewBox={icon.vb}
      width={sz} height={sz}
      fill={color}
      style={{ display: 'block', overflow: 'visible' }}
      dangerouslySetInnerHTML={{ __html: icon.s }}
    />
  );
}

function Bar({ val, max = 1, clr }) {
  const pct = Math.min(100, (val / max) * 100);
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
      <div style={{ flex: 1, height: 5, background: 'var(--color-border-tertiary)', borderRadius: 3, overflow: 'hidden' }}>
        <div style={{ width: `${pct}%`, height: '100%', background: clr, borderRadius: 3 }} />
      </div>
      <span style={{ fontSize: 11, minWidth: 40, color: 'var(--color-text-secondary)' }}>{val.toFixed(3)}</span>
    </div>
  );
}

function StoreGrid({ data, fxMap, onFixtureClick }) {
  const CW = 44, CH = 14;
  return (
    <div style={{ overflowY: 'auto', maxHeight: 560 }}>
      <div style={{ display: 'flex' }}>
        <div style={{ width: 22, flexShrink: 0 }}>
          {Array.from({ length: data.N_I }, (_, idx) => {
            const i = data.N_I - idx;
            return (
              <div key={i} style={{ height: CH, display: 'flex', alignItems: 'center', justifyContent: 'flex-end', paddingRight: 3, fontSize: 8, color: 'var(--color-text-tertiary)' }}>
                {i % 5 === 0 ? i : ''}
              </div>
            );
          })}
        </div>
        <div>
          {Array.from({ length: data.N_I }, (_, rowIdx) => {
            const i = data.N_I - rowIdx;
            return (
              <div key={i} style={{ display: 'flex' }}>
                {Array.from({ length: data.N_J }, (_, colIdx) => {
                  const j = colIdx + 1;
                  const v = data.grid[i - 1][j - 1];
                  const aij = `A(${i},${j})`;
                  const fx = fxMap[aij];
                  let bg = 'var(--color-background-primary)';
                  if (v === 1) bg = '#3C3A38';
                  else if (v === 2 && fx) bg = FTCLR[fx.fixture_type] || '#C0C8D8';
                  return (
                    <div key={j}
                      onClick={() => v === 2 && fx && onFixtureClick(fx)}
                      title={fx ? `${aij} · ${fx.fixture_type} · fix_idx: ${fx.fix_idx}` : aij}
                      style={{
                        width: CW, height: CH, background: bg,
                        border: '0.5px solid rgba(0,0,0,0.05)',
                        cursor: v === 2 && fx ? 'pointer' : 'default',
                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                        fontSize: 7, fontWeight: 500, color: 'rgba(0,0,0,0.5)'
                      }}>
                      {v === 2 && fx ? fx.fix_idx : ''}
                    </div>
                  );
                })}
              </div>
            );
          })}
          <div style={{ display: 'flex' }}>
            {Array.from({ length: data.N_J }, (_, idx) => (
              <div key={idx} style={{ width: CW, textAlign: 'center', fontSize: 8, color: 'var(--color-text-tertiary)', paddingTop: 3 }}>
                {idx + 1}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

function ProductDetail({ lot, fxMap, onClose }) {
  const clr = CHEX[lot.ColorGroup] || '#888';
  const fxIdx = (() => {
    for (const k of Object.keys(fxMap)) {
      if (fxMap[k].lots.find(l => l.lot_ID === lot.lot_ID)) return fxMap[k].fix_idx;
    }
    return '-';
  })();
  return (
    <div style={{ borderLeft: '0.5px solid var(--color-border-tertiary)', paddingLeft: 18, minWidth: 230 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14 }}>
        <span style={{ fontSize: 11, fontWeight: 500, color: 'var(--color-text-secondary)', letterSpacing: '0.05em' }}>ITEM DETAIL</span>
        <button onClick={onClose} style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: 16, color: 'var(--color-text-secondary)', padding: '0 2px' }}>×</button>
      </div>
      <div style={{ display: 'flex', gap: 12, alignItems: 'center', marginBottom: 14 }}>
        <div style={{ width: 68, height: 68, border: `1px solid ${clr}40`, borderRadius: 8, background: `${clr}0A`, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
          <CategoryIcon cat={lot.category} color={clr} sz={52}/>
        </div>
        <div>
          <div style={{ fontSize: 14, fontWeight: 500 }}>{lot.ItemOption}</div>
          <div style={{ fontSize: 11, color: 'var(--color-text-secondary)', marginTop: 1 }}>{lot.category}</div>
          <div style={{ display: 'flex', gap: 4, marginTop: 5, flexWrap: 'wrap' }}>
            <span style={{ fontSize: 9, background: `${clr}18`, color: clr, padding: '2px 7px', borderRadius: 8, border: `0.5px solid ${clr}40` }}>{lot.ColorGroup}</span>
            <span style={{ fontSize: 9, background: 'var(--color-background-secondary)', color: 'var(--color-text-secondary)', padding: '2px 7px', borderRadius: 8 }}>{lot.LifeStyleGroup}</span>
          </div>
        </div>
      </div>
      <div style={{ background: 'var(--color-background-secondary)', borderRadius: 7, padding: '9px 11px', marginBottom: 12 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 10, color: 'var(--color-text-secondary)' }}>
          <span>base price</span><span style={{ textDecoration: 'line-through' }}>₺{lot.base_price.toLocaleString()}</span>
        </div>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', marginTop: 3 }}>
          <span style={{ fontSize: 10, color: 'var(--color-text-secondary)' }}>effective</span>
          <span style={{ fontSize: 15, fontWeight: 500 }}>₺{lot.effective_price.toLocaleString()}</span>
        </div>
        {lot.discount_rate > 0 && (
          <div style={{ fontSize: 10, color: '#C03030', marginTop: 1 }}>−{Math.round(lot.discount_rate * 100)}% off</div>
        )}
      </div>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
        <div>
          <div style={{ fontSize: 10, color: 'var(--color-text-secondary)', marginBottom: 3 }}>saleability score</div>
          <Bar val={lot.saleability_score} max={1} clr="#3A7050" />
        </div>
        <div>
          <div style={{ fontSize: 10, color: 'var(--color-text-secondary)', marginBottom: 3 }}>location score (L_type)</div>
          <Bar val={lot.L_type_score} max={1.35} clr="#1B3A6B" />
        </div>
      </div>
      <div style={{ marginTop: 12, paddingTop: 10, borderTop: '0.5px solid var(--color-border-tertiary)', display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 7 }}>
        {[['lot ID', lot.lot_ID], ['mode', lot.mode], ['row · col', `r${lot.r} · c${lot.c}`], ['fix_idx', fxIdx]].map(([k, v]) => (
          <div key={k}>
            <div style={{ fontSize: 9, color: 'var(--color-text-secondary)' }}>{k}</div>
            <div style={{ fontSize: 11, fontWeight: 500, marginTop: 1 }}>{v}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

function getRowStyle(r, max_r, fixtureType, rowLots) {
  const allHanging = rowLots.length > 0 && rowLots.every(l => l.mode === 'hanging' || l.mode === 'front_facing');
  if (allHanging) return 'hanging';
  if (fixtureType.startsWith('wall_hanger')) {
    if (r === max_r) return 'top_shelf';
    if (r === 1) return 'wood_platform';
  }
  if (fixtureType.startsWith('table')) return 'table';
  return 'shelf';
}

function getVisualMap(rowLots, max_c) {
  const m = {};
  if (rowLots.length === 2 && max_c >= 5 && rowLots.every(l => l.mode === 'normal')) {
    const sorted = [...rowLots].sort((a,b) => a.c - b.c);
    m[1] = sorted[0]; m[max_c] = sorted[1];
  } else {
    rowLots.forEach(l => { m[l.c] = l; });
  }
  return m;
}

function ItemCell({ lot, isSel, onClick, w, h }) {
  if (!lot) return <div style={{ width: w, height: h, flexShrink: 0 }} />;
  const clr = CHEX[lot.ColorGroup] || '#909090';
  const isFront = lot.mode === 'front_facing';
  const fw = isFront ? Math.round(w * 1.15) : w;
  const fh = isFront ? Math.round(h * 1.15) : h;
  const iconSz = Math.round(fw * 0.74);
  return (
    <div onClick={() => onClick(isSel ? null : lot)}
      style={{
        width: fw, height: fh, flexShrink: 0,
        border: isSel ? `2px solid ${clr}` : `0.5px solid ${clr}30`,
        borderRadius: 5,
        background: isSel ? `${clr}18` : `${clr}08`,
        display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'flex-end',
        cursor: 'pointer', position: 'relative',
        transition: 'all 0.1s', paddingBottom: 3
      }}>
      {isFront && (
        <div style={{ position: 'absolute', top: 2, right: 3, fontSize: 7, color: clr, fontWeight: 700, background: 'rgba(255,255,255,0.85)', padding: '1px 3px', borderRadius: 3 }}>FF</div>
      )}
      {lot.mode === 'hanging' && (
        <div style={{ position: 'absolute', top: 0, left: '50%', transform: 'translateX(-50%)', width: 1.5, height: 7, background: '#AAA' }}/>
      )}
      <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '6px 2px 0' }}>
        <CategoryIcon cat={lot.category} color={clr} sz={iconSz}/>
      </div>
      <div style={{ fontSize: 7, color: clr, textAlign: 'center', lineHeight: 1.1, padding: '0 2px', maxWidth: fw - 4, overflow: 'hidden', whiteSpace: 'nowrap', textOverflow: 'ellipsis', opacity: 0.8 }}>
        {lot.ItemOption}
      </div>
    </div>
  );
}

function FixtureRow({ r, max_r, fixtureType, rowLots, max_c, cellW, cellH, activeLot, onLotClick }) {
  const rowStyle = getRowStyle(r, max_r, fixtureType, rowLots);
  const vmap = getVisualMap(rowLots, max_c);
  let topDec = null, bottomDec = null, surfaceBg = 'transparent';
  if (rowStyle === 'hanging') {
    topDec = <div style={{ height: 5, marginLeft: -4, marginRight: -4, marginBottom: 2, background: 'linear-gradient(to bottom, #E8E6E2, #C8C6C2 50%, #909090)', borderRadius: 2.5, boxShadow: '0 1px 0 rgba(0,0,0,0.06)' }}/>;
  } else if (rowStyle === 'top_shelf') {
    surfaceBg = 'rgba(248,246,242,0.5)';
    topDec = <div style={{ height: 4, marginLeft: -4, marginRight: -4, background: 'linear-gradient(to bottom, #DDD9D2, #BCB8B0)', borderRadius: '2px 2px 0 0' }}/>;
    bottomDec = <div style={{ height: 4, marginLeft: -4, marginRight: -4, background: 'linear-gradient(to bottom, #C8C6C2, #909090)', borderRadius: '0 0 2px 2px', boxShadow: '0 1px 1px rgba(0,0,0,0.08)' }}/>;
  } else if (rowStyle === 'wood_platform') {
    bottomDec = <div style={{ marginLeft: -4, marginRight: -4, marginTop: 2 }}><div style={{ height: 5, background: 'linear-gradient(to bottom, #DDC5A0, #B89968)' }}/><div style={{ height: 3, background: '#9A7E54' }}/></div>;
  } else if (rowStyle === 'table') {
    bottomDec = <div style={{ height: 4, marginLeft: -4, marginRight: -4, background: 'linear-gradient(to bottom, #DDC5A0, #A88860)', marginTop: 2 }}/>;
  } else {
    bottomDec = <div style={{ height: 2, marginLeft: -4, marginRight: -4, background: '#C0BCB6', marginTop: 2 }}/>;
  }
  return (
    <div style={{ marginBottom: 6 }}>
      <div style={{ display: 'flex', alignItems: 'stretch' }}>
        <div style={{ width: 24, fontSize: 9, color: 'var(--color-text-tertiary)', textAlign: 'right', paddingRight: 5, paddingTop: 12, flexShrink: 0 }}>r{r}</div>
        <div style={{ flex: 1 }}>
          {topDec}
          <div style={{ background: surfaceBg, padding: rowStyle === 'top_shelf' ? '6px 4px' : '0 4px' }}>
            <div style={{ display: 'flex', gap: 4, alignItems: 'flex-end' }}>
              {Array.from({ length: max_c }, (_, i) => {
                const c = i + 1;
                const lot = vmap[c];
                const isSel = lot && activeLot?.lot_ID === lot.lot_ID;
                return <ItemCell key={c} lot={lot} isSel={isSel} onClick={onLotClick} w={cellW} h={cellH}/>;
              })}
            </div>
          </div>
          {bottomDec}
        </div>
      </div>
    </div>
  );
}

function FixturePlanogram({ fx, fxMap, onBack, onLotClick, activeLot }) {
  const hasSide = !!activeLot;
  const planAvail = hasSide ? 380 : 620;
  const cellW = Math.max(38, Math.min(74, Math.floor((planAvail - 40) / fx.max_c)));
  const cellH = Math.round(cellW * 1.3);
  return (
    <div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '12px 0 14px', borderBottom: '0.5px solid var(--color-border-tertiary)', marginBottom: 16 }}>
        <button onClick={onBack} style={{ background: 'none', border: '0.5px solid var(--color-border-secondary)', borderRadius: 6, padding: '4px 10px', cursor: 'pointer', fontSize: 11 }}>← store</button>
        <div style={{ display: 'flex', alignItems: 'baseline', gap: 8, flexWrap: 'wrap' }}>
          <span style={{ fontSize: 15, fontWeight: 500 }}>{fx.A_ij}</span>
          <span style={{ fontSize: 11, color: 'var(--color-text-secondary)' }}>{fx.fixture_type.replace(/_/g, ' ')}</span>
          <span style={{ fontSize: 10, background: 'var(--color-background-secondary)', padding: '2px 8px', borderRadius: 9, color: 'var(--color-text-secondary)' }}>
            fix_idx: <strong style={{ color: 'var(--color-text-primary)' }}>{fx.fix_idx}</strong>
          </span>
          <span style={{ fontSize: 10, color: 'var(--color-text-tertiary)' }}>{fx.max_r}r × {fx.max_c}c · {fx.lots.length} items</span>
        </div>
      </div>
      <div style={{ display: 'flex', gap: 0 }}>
        <div style={{ flexShrink: 0, padding: '8px 6px', background: 'linear-gradient(to bottom, #FAF8F3, #F2EFE8)', borderRadius: 8, border: '0.5px solid rgba(0,0,0,0.08)' }}>
          {Array.from({ length: fx.max_r }, (_, rIdx) => {
            const r = fx.max_r - rIdx;
            const rowLots = fx.lots.filter(l => l.r === r);
            return <FixtureRow key={r} r={r} max_r={fx.max_r} fixtureType={fx.fixture_type} rowLots={rowLots} max_c={fx.max_c} cellW={cellW} cellH={cellH} activeLot={activeLot} onLotClick={onLotClick}/>;
          })}
          <div style={{ paddingLeft: 29, marginTop: 6, fontSize: 9, color: 'var(--color-text-tertiary)' }}>FF = front facing · click icon for details</div>
        </div>
        {activeLot && <ProductDetail lot={activeLot} fxMap={fxMap} onClose={() => onLotClick(null)} />}
      </div>
    </div>
  );
}

const DATA_URL = `${import.meta.env.BASE_URL}data/assignment.json`;

export default function App() {
  const [view, setView] = useState('grid');
  const [activeFx, setActiveFx] = useState(null);
  const [activeLot, setActiveLot] = useState(null);
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetch(DATA_URL)
      .then(res => {
        if (!res.ok) throw new Error(`Failed to load ${DATA_URL} (${res.status})`);
        return res.json();
      })
      .then(setData)
      .catch(err => setError(err.message));
  }, []);

  const fxMap = useMemo(() => {
    if (!data) return {};
    const m = {};
    data.fixtures.forEach(f => { m[f.A_ij] = f; });
    return m;
  }, [data]);

  if (error) {
    return (
      <div style={{ padding: 24, fontFamily: 'var(--font-sans)', color: '#C03030' }}>
        Could not load assignment data: {error}.<br/>
        Run notebooks/04_cp_sat_assignment to regenerate public/data/assignment.json.
      </div>
    );
  }

  if (!data) {
    return (
      <div style={{ padding: 24, fontFamily: 'var(--font-sans)', color: 'var(--color-text-secondary)' }}>
        Loading store planogram…
      </div>
    );
  }

  const totalItems = data.fixtures.reduce((sum, f) => sum + f.lots.length, 0);

  return (
    <div style={{ fontFamily: 'var(--font-sans)', color: 'var(--color-text-primary)' }}>
      <div style={{ padding: '10px 16px 8px', borderBottom: '0.5px solid var(--color-border-tertiary)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div>
          <div style={{ fontSize: 12, fontWeight: 500, letterSpacing: '0.08em' }}>STORE PLANOGRAM · IPEKYOL</div>
          <div style={{ fontSize: 10, color: 'var(--color-text-secondary)', marginTop: 1 }}>model2 · {data.fixtures.length} fixtures · {totalItems} ItemOptions · {view === 'grid' ? 'click fixture to open planogram' : `${activeFx?.A_ij} — click item for details`}</div>
        </div>
        {view === 'fixture' && (
          <div style={{ fontSize: 10, background: FTCLR[activeFx?.fixture_type] || '#C0C8D8', padding: '3px 10px', borderRadius: 8, color: 'rgba(0,0,0,0.6)', fontWeight: 500 }}>
            {activeFx?.fixture_type.replace(/_/g, ' ')}
          </div>
        )}
      </div>
      {view === 'grid' && (
        <div style={{ padding: '8px 14px 14px' }}>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 8 }}>
            {Object.entries(FTCLR).map(([t, c]) => (
              <div key={t} style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                <div style={{ width: 9, height: 9, background: c, border: '0.5px solid rgba(0,0,0,0.12)', borderRadius: 2 }} />
                <span style={{ fontSize: 8, color: 'var(--color-text-secondary)' }}>{t.replace(/_/g, ' ')}</span>
              </div>
            ))}
            <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
              <div style={{ width: 9, height: 9, background: '#3C3A38', borderRadius: 2 }} />
              <span style={{ fontSize: 8, color: 'var(--color-text-secondary)' }}>blocked</span>
            </div>
          </div>
          <StoreGrid data={data} fxMap={fxMap} onFixtureClick={fx => { setActiveFx(fx); setActiveLot(null); setView('fixture'); }} />
        </div>
      )}
      {view === 'fixture' && activeFx && (
        <div style={{ padding: '0 16px 20px' }}>
          <FixturePlanogram fx={activeFx} fxMap={fxMap} onBack={() => { setView('grid'); setActiveFx(null); setActiveLot(null); }} onLotClick={lot => setActiveLot(lot)} activeLot={activeLot}/>
        </div>
      )}
    </div>
  );
}
